"""Seat students in rows ordered by last name."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _row_line(number: int, row: List[Student]) -> str:
    names = " | ".join(s.display_name for s in row)
    return f"Row {number}: {names}"

def _chunks(items, size):
    return [items[i:i + size]
            for i in range(0, len(items), size)]

def _by_name(students):
    key = lambda s: (s.last_name, s.first_name)
    return sorted(students, key=key)

# ---
def seat_rows(students, per_row):
    if per_row < 1 or not students:
        raise ProjectError("need students and seats")
    rows = _chunks(_by_name(students), per_row)
    return [_row_line(n, r) for n, r in enumerate(rows, 1)]

