# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _student(last, first):
    return Student("1", last, first, "A")

class SeatRowsTests(unittest.TestCase):
    def test_sorts_and_splits_rows(self):
        people = [
            _student("Halloway", "Juno"),
            _student("Zed", "Amy"),
            _student("Dunmere", "Piet")
        ]
        self.assertEqual(
            seat_rows(people, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zed, Amy"
            ]
        )

    def test_bad_seat_count(self):
        people = [_student("Zed", "Amy")]
        for bad in (0, -1):
            with self.assertRaises(ProjectError):
                seat_rows(people, bad)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)
